solution.solution.c:
#include <time.h>

size_t format_utc(time_t t, char *buf, size_t size)
{
    struct tm *tm = gmtime(&t);
    if (!tm || size == 0) return 0;
    return strftime(buf, size, "%Y-%m-%d %H:%M:%S", tm);
}

int weekday(int year, int month, int day)
{
    struct tm t = {0};
    t.tm_year = year - 1900;
    t.tm_mon = month - 1;
    t.tm_mday = day;
    t.tm_hour = 12;
    t.tm_isdst = -1;
    if (mktime(&t) == (time_t)-1) return -1;
    if (t.tm_year != year - 1900 || t.tm_mon != month - 1 || t.tm_mday != day) return -1;
    return t.tm_wday;
}

unitTests:
TEST("format the epoch and a later moment") { char b[32]; CHECK_EQ((int)format_utc(0, b, sizeof b), 19); CHECK_STR(b, "1970-01-01 00:00:00"); format_utc(1767264300, b, sizeof b); CHECK_STR(b, "2026-01-01 10:45:00"); }
TEST("too small a buffer") { char b[10]; CHECK_EQ((int)format_utc(0, b, sizeof b), 0); }
TEST("weekdays") { CHECK_EQ(weekday(2026, 11, 20), 5); CHECK_EQ(weekday(2000, 1, 1), 6); CHECK_EQ(weekday(2024, 2, 29), 4); }
TEST("dates that do not exist") { CHECK_EQ(weekday(2026, 4, 31), -1); CHECK_EQ(weekday(2023, 2, 29), -1); CHECK_EQ(weekday(2026, 13, 1), -1); }

